#!/usr/bin/env python3
"""Copies a curated set of OFL fonts from a sparse clone of github.com/google/fonts into platform/web/vendor/fonts/more/
and writes more.css + js/data/fonts_more.js. Usage: tools/vendor_fonts.py /path/to/google-fonts-clone
Clone: GIT_LFS_SKIP_SMUDGE=1 git clone --depth 1 --filter=blob:none --sparse https://github.com/google/fonts.git gf
       cd gf && git sparse-checkout set ofl/<dir> ...   (dirs = keys below)"""
import json, os, re, shutil, sys
src = sys.argv[1]; root = os.path.join(os.path.dirname(__file__), "..", "platform", "web")
out = os.path.join(root, "vendor", "fonts", "more"); os.makedirs(os.path.join(out, "licenses"), exist_ok=True)
# dir: (family, script, category)   script: hi = Devanagari, other Indian scripts, en = Latin only
F = {
 "mukta": ("Mukta", "hi", "sans"), "hind": ("Hind", "hi", "sans"), "poppins": ("Poppins", "hi", "sans"), "baloo2": ("Baloo 2", "hi", "display"),
 "baloobhai2": ("Baloo Bhai 2", "gu", "display"), "notoserifdevanagari": ("Noto Serif Devanagari", "hi", "serif"), "martel": ("Martel", "hi", "serif"),
 "yantramanav": ("Yantramanav", "hi", "sans"), "kadwa": ("Kadwa", "hi", "serif"), "sarpanch": ("Sarpanch", "hi", "display"), "palanquin": ("Palanquin", "hi", "sans"),
 "rajdhani": ("Rajdhani", "hi", "display"), "biryani": ("Biryani", "hi", "sans"), "cambay": ("Cambay", "hi", "sans"), "sarala": ("Sarala", "hi", "sans"),
 "asar": ("Asar", "hi", "serif"), "inknutantiqua": ("Inknut Antiqua", "hi", "serif"), "jaldi": ("Jaldi", "hi", "sans"), "khula": ("Khula", "hi", "sans"),
 "vesperlibre": ("Vesper Libre", "hi", "serif"), "rhodiumlibre": ("Rhodium Libre", "hi", "serif"), "pragatinarrow": ("Pragati Narrow", "hi", "sans"),
 "hindvadodara": ("Hind Vadodara", "gu", "sans"), "hindsiliguri": ("Hind Siliguri", "bn", "sans"), "hindmadurai": ("Hind Madurai", "ta", "sans"), "hindguntur": ("Hind Guntur", "te", "sans"),
 "bebasneue": ("Bebas Neue", "en", "display"), "pacifico": ("Pacifico", "en", "script"), "lobster": ("Lobster", "en", "script"), "playfairdisplay": ("Playfair Display", "en", "serif"),
 "montserrat": ("Montserrat", "en", "sans"), "oswald": ("Oswald", "en", "display"), "anton": ("Anton", "en", "display"), "dancingscript": ("Dancing Script", "en", "script"),
 "caveat": ("Caveat", "en", "script"), "bangers": ("Bangers", "en", "display"), "abrilfatface": ("Abril Fatface", "en", "display"), "cinzel": ("Cinzel", "en", "serif"),
 "righteous": ("Righteous", "en", "display"), "greatvibes": ("Great Vibes", "en", "script"), "lora": ("Lora", "en", "serif"), "raleway": ("Raleway", "en", "sans"),
 "roboto": ("Roboto", "en", "sans"), "opensans": ("Open Sans", "en", "sans"), "nunito": ("Nunito", "en", "sans"), "comfortaa": ("Comfortaa", "en", "display"),
 "fredoka": ("Fredoka", "en", "display"), "lilitaone": ("Lilita One", "en", "display"), "staatliches": ("Staatliches", "en", "display"), "alfaslabone": ("Alfa Slab One", "en", "display"),
 "archivoblack": ("Archivo Black", "en", "display"), "josefinsans": ("Josefin Sans", "en", "sans"), "quicksand": ("Quicksand", "en", "sans"), "spacegrotesk": ("Space Grotesk", "en", "sans"),
 "bungee": ("Bungee", "en", "display"), "sigmarone": ("Sigmar One", "en", "display"), "pressstart2p": ("Press Start 2P", "en", "display"),
}
css, items = [], []
for d, (fam, script, cat) in F.items():
    p = os.path.join(src, "ofl", d)
    if not os.path.isdir(p): print("missing", d); continue
    files = [f for f in os.listdir(p) if f.endswith(".ttf") and "Italic" not in f]
    vf = [f for f in files if "[" in f]; faces = []
    if vf: faces = [(vf[0], "100 900")]
    else:
        reg = [f for f in files if f.endswith("-Regular.ttf")]; bold = [f for f in files if f.endswith("-Bold.ttf")]
        if reg: faces.append((reg[0], "400"))
        if bold: faces.append((bold[0], "700"))
    if not faces: print("no ttf", d); continue
    for f, w in faces:
        name = d + ("-vf" if "[" in f else "-" + w) + ".ttf"; shutil.copy(os.path.join(p, f), os.path.join(out, name))
        css.append('@font-face{font-family:"%s";src:url("%s") format("truetype");font-weight:%s;font-display:swap}' % (fam, name, w))
    lic = next((x for x in os.listdir(p) if x.upper().startswith(("OFL", "LICENSE"))), None)
    if lic: shutil.copy(os.path.join(p, lic), os.path.join(out, "licenses", "OFL-" + d + ".txt"))
    items.append({"family": fam, "script": script, "cat": cat, "bold": any(w != "400" for _, w in faces)})
open(os.path.join(out, "more.css"), "w").write("\n".join(css) + "\n")
open(os.path.join(root, "js", "data", "fonts_more.js"), "w").write("// generated by tools/vendor_fonts.py: extra OFL fonts (google/fonts). Files load only when a font is used.\nexport const MORE_FONTS = " + json.dumps(items, ensure_ascii=False, indent=1) + ";\n")
print(len(items), "families,", sum(os.path.getsize(os.path.join(out, f)) for f in os.listdir(out) if f.endswith('.ttf')) // 1024, "KB")
